function readHistoricalSources() {
  const result = {};
  for (const [name, entry] of Object.entries(SOURCES)) {
    const source = Buffer.from(entry.base64, 'base64').toString('utf8');
    if (crypto.createHash('sha256').update(source).digest('hex') !== entry.sha256) throw new Error(`historical source digest mismatch: ${name}`);
    result[name] = source;
  }
  return Object.freeze(result);
}

module.exports = { SOURCES, readHistoricalSources };
